cd /workspace && node --input-type=module -e "
import {nextRetry} from './retry-budget.js';

// Brute-force reference with exact BigInt arithmetic.
function reference(o) {
  if (o.retryable === false) return {retry:false,delayMs:null,reason:'non-retryable'};
  let exp = BigInt(o.baseMs);
  for (let i = 1; i < o.attempt; i++) { exp *= 2n; if (exp > BigInt(o.maxDelayMs)) break; }
  if (exp > BigInt(o.maxDelayMs)) exp = BigInt(o.maxDelayMs);
  let wait = o.retryAfterMs === null ? Number(exp) : Math.max(Number(exp), o.retryAfterMs);
  if (o.elapsedMs > o.budgetMs || wait > o.budgetMs - o.elapsedMs) return {retry:false,delayMs:null,reason:'budget-exhausted'};
  return {retry:true,delayMs:wait,reason:'scheduled'};
}

let n = 0;
for (let attempt = 1; attempt <= 60; attempt++) {
  for (const baseMs of [0,1,3,7,10,99,100,101,2**20,2**40]) {
    for (const maxDelayMs of [0,1,10,99,100,101,2**30,2**52]) {
      for (const retryAfterMs of [null,0,5,100,1000,2**45]) {
        for (const elapsedMs of [0,1,90,99,100,101,200]) {
          for (const budgetMs of [0,90,99,100,101,500,2**48]) {
            const o = {attempt,elapsedMs,baseMs,maxDelayMs,budgetMs,retryAfterMs,retryable:true};
            const got = nextRetry(o), want = reference(o);
            if (JSON.stringify(got) !== JSON.stringify(want)) {
              console.log('MISMATCH', o, 'got', got, 'want', want);
              process.exit(1);
            }
            n++;
          }
        }
      }
    }
  }
}
// also random large-attempt cases (reference uses early break so it is fast)
for (let i = 0; i < 20000; i++) {
  const attempt = 1 + Math.floor(Math.random() * 2**53);
  const baseMs = Math.floor(Math.random() * 2**40);
  const maxDelayMs = Math.floor(Math.random() * 2**53);
  const retryAfterMs = Math.random() < 0.5 ? null : Math.floor(Math.random() * 2**53);
  const elapsedMs = Math.floor(Math.random() * 2**53);
  const budgetMs = Math.floor(Math.random() * 2**53);
  const o = {attempt,elapsedMs,baseMs,maxDelayMs,budgetMs,retryAfterMs,retryable:true};
  const got = nextRetry(o), want = reference(o);
  if (JSON.stringify(got) !== JSON.stringify(want)) {
    console.log('MISMATCH', o, 'got', got, 'want', want);
    process.exit(1);
  }
  n++;
}
console.log('OK, checked', n + 20000, 'cases');
"

