+// nextRetry(options) is a pure decision function: it never sleeps, reads the
+// clock, or makes network requests. The CLI at the bottom runs only when this
+// file is executed directly (node retry-budget.js INPUT_JSON_FILE).
+
+import {readFileSync, realpathSync} from 'node:fs';
+import {pathToFileURL} from 'node:url';
+
+function isNonnegativeSafeInteger(value) {
+  return Number.isSafeInteger(value) && value >= 0;
 }
+
+function validateOptions(options) {
+  if (options === null || typeof options !== 'object' || Array.isArray(options)) {
+    throw new Error('options must be a non-null, non-array object');
+  }
+  if (!Number.isSafeInteger(options.attempt) || options.attempt < 1) {
+    throw new Error('attempt must be a positive safe integer');
+  }
+  for (const key of ['elapsedMs', 'baseMs', 'maxDelayMs', 'budgetMs']) {
+    if (!isNonnegativeSafeInteger(options[key])) {
+      throw new Error(`${key} must be a nonnegative safe integer`);
+    }
+  }
+  if (options.retryAfterMs !== null && !isNonnegativeSafeInteger(options.retryAfterMs)) {
+    throw new Error('retryAfterMs must be null or a nonnegative safe integer');
+  }
+  if (typeof options.retryable !== 'boolean') {
+    throw new Error('retryable must be a boolean');
+  }
+}
+
+// Computes baseMs * 2 ** (attempt - 1), capped at maxDelayMs, exactly.
+// Doublings are applied one at a time but the loop is bounded by
+// log2(maxDelayMs / baseMs) (at most 53 iterations for safe integers), never
+// by attempt, so huge attempts terminate instantly. A zero base yields a zero
+// delay for every attempt without hitting 0 * Infinity = NaN.
+function cappedExponentialDelay(baseMs, attempt, maxDelayMs) {
+  if (baseMs === 0) return 0;
+  let delay = baseMs < maxDelayMs ? baseMs : maxDelayMs;
+  for (let applied = 1; applied < attempt && delay < maxDelayMs; applied++) {
+    // min(2 * delay, maxDelayMs) without overflowing: when doubling would
+    // pass the cap, the cap itself is the exact answer.
+    delay = delay <= maxDelayMs - delay ? delay + delay : maxDelayMs;
+  }
+  return delay;
+}
+
+export function nextRetry(options) {
+  validateOptions(options);
+  if (options.retryable === false) {
+    return {retry:false,delayMs:null,reason:'non-retryable'};
+  }
+  const exponential = cappedExponentialDelay(options.baseMs, options.attempt, options.maxDelayMs);
+  // A server-requested hint is a minimum wait and is NOT capped by maxDelayMs.
+  const wait = options.retryAfterMs === null ? exponential : Math.max(exponential, options.retryAfterMs);
+  // Equality is allowed: scheduling the retry exactly at the budget boundary
+  // (wait === budgetMs - elapsedMs) is valid.
+  if (options.elapsedMs > options.budgetMs || wait > options.budgetMs - options.elapsedMs) {
+    return {retry:false,delayMs:null,reason:'budget-exhausted'};
+  }
+  return {retry:true,delayMs:wait,reason:'scheduled'};
+}
+
+function fail(message) {
+  process.stderr.write(`${message}\n`);
+  process.exitCode = 2;
+}
+
+function runCli() {
+  const args = process.argv.slice(2);
+  if (args.length !== 1) {
+    fail('usage: node retry-budget.js INPUT_JSON_FILE');
+    return;
+  }
+  const inputPath = args[0];
+  let text;
+  try {
+    text = readFileSync(inputPath, 'utf8');
+  } catch (error) {
+    fail(`cannot read input file: ${error.message}`);
+    return;
+  }
+  if (text.charCodeAt(0) === 0xfeff) text = text.slice(1);
+  let options;
+  try {
+    options = JSON.parse(text);
+  } catch (error) {
+    fail(`invalid JSON: ${error.message}`);
+    return;
+  }
+  let result;
+  try {
+    result = nextRetry(options);
+  } catch (error) {
+    fail(`invalid options: ${error.message}`);
+    return;
+  }
+  // A consumer that closes the pipe early (e.g. `| head`) would otherwise
+  // surface an unhandled 'error' event on process.stdout.
+  process.stdout.on('error', error => {
+    if (error && error.code === 'EPIPE') return;
+    process.exitCode = 1;
+  });
+  try {
+    process.stdout.write(`${JSON.stringify(result)}\n`);
+  } catch (error) {
+    if (!error || error.code !== 'EPIPE') throw error;
+  }
+}
