+  if (typeof process.argv[1] !== 'string') return false;
+  const candidates = [process.argv[1]];
+  try {
+    // Also match a realpath so symlinked invocations still detect direct runs.
+    candidates.push(realpathSync(process.argv[1]));
+  } catch {
+    // Unresolvable path: fall through to the direct comparison only.
+  }
+  return candidates.some(path => {
+    try {
+      return import.meta.url === pathToFileURL(path).href;
+    } catch {
+      return false;
+    }
+  });
+}
