import test from 'node:test';
import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {mkdtempSync, writeFileSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {fileURLToPath} from 'node:url';
import {nextRetry} from '../retry-budget.js';

const CLI_PATH = fileURLToPath(new URL('../retry-budget.js', import.meta.url));
const base = {attempt:1, elapsedMs:0, baseMs:10, maxDelayMs:100, budgetMs:1000, retryAfterMs:null, retryable:true};

// ---------- validation ----------

test('throws an Error for null, undefined, arrays, and non-objects', () => {
  for (const bad of [null, undefined, 5, 'x', true, [base], /re/, () => {}]) {
    assert.throws(() => nextRetry(bad), Error, String(bad));
  }
});

test('throws when any required field is missing', () => {
  for (const key of ['attempt','elapsedMs','baseMs','maxDelayMs','budgetMs','retryAfterMs','retryable']) {
    const o = {...base};
    delete o[key];
    assert.throws(() => nextRetry(o), Error, key);
  }
});

test('throws on wrong types and out-of-range values', () => {
  const bad = [
    {attempt:'1'}, {attempt:1.5}, {attempt:0}, {attempt:-1}, {attempt:2 ** 53}, {attempt:NaN}, {attempt:Infinity},
    {elapsedMs:-1}, {elapsedMs:'0'}, {elapsedMs:1.25},
    {baseMs:-0.5}, {baseMs:Infinity},
    {maxDelayMs:NaN}, {maxDelayMs:null},
    {budgetMs:-1}, {budgetMs:2 ** 53},
    {retryAfterMs:'10'}, {retryAfterMs:-1}, {retryAfterMs:1.25}, {retryAfterMs:true},
    {retryable:1}, {retryable:0}, {retryable:'true'}, {retryable:null},
  ];
  for (const patch of bad) {
    assert.throws(() => nextRetry({...base, ...patch}), Error, JSON.stringify(patch));
  }
});

test('validates every field even when retryable is false', () => {
  assert.throws(() => nextRetry({...base, retryable:false, attempt:'1'}));
  assert.throws(() => nextRetry({...base, retryable:false, budgetMs:-5}));
  assert.throws(() => nextRetry({...base, retryable:false, retryAfterMs:'10'}));
  assert.throws(() => nextRetry({...base, retryable:false, baseMs:NaN}));
});

test('extra fields are ignored', () => {
  assert.deepEqual(nextRetry({...base, foo:'bar', n: 42}), {retry:true, delayMs:10, reason:'scheduled'});
});

test('frozen options work and the input is not mutated', () => {
  const frozen = Object.freeze({...base});
  assert.deepEqual(nextRetry(frozen), {retry:true, delayMs:10, reason:'scheduled'});
  assert.deepEqual(frozen, base);
});

test('result objects have exactly the documented keys', () => {
  assert.deepEqual(Object.keys(nextRetry(base)).sort(), ['delayMs','reason','retry']);
  assert.deepEqual(Object.keys(nextRetry({...base, retryable:false})).sort(), ['delayMs','reason','retry']);
  assert.deepEqual(Object.keys(nextRetry({...base, budgetMs:0})).sort(), ['delayMs','reason','retry']);
});

// ---------- non-retryable ----------

test('non-retryable returns exactly the decision object', () => {
  assert.deepEqual(nextRetry({...base, retryable:false}), {retry:false, delayMs:null, reason:'non-retryable'});
  // even when the budget would obviously be exhausted
  assert.deepEqual(nextRetry({...base, retryable:false, elapsedMs:99999}), {retry:false, delayMs:null, reason:'non-retryable'});
});

// ---------- exponential delay ----------

test('exponential delay doubles per attempt and caps at maxDelayMs', () => {
  assert.equal(nextRetry({...base, attempt:1}).delayMs, 10);
  assert.equal(nextRetry({...base, attempt:2}).delayMs, 20);
  assert.equal(nextRetry({...base, attempt:3}).delayMs, 40);
  assert.equal(nextRetry({...base, attempt:4}).delayMs, 80);
  assert.equal(nextRetry({...base, attempt:5}).delayMs, 100); // 160 capped to 100
  assert.equal(nextRetry({...base, attempt:10}).delayMs, 100);
});

test('exact exponential values before capping', () => {
  const o = {attempt:10, elapsedMs:0, baseMs:3, maxDelayMs:1000000, budgetMs:1000000000, retryAfterMs:null, retryable:true};
  assert.deepEqual(nextRetry(o), {retry:true, delayMs:3 * 512, reason:'scheduled'});
});

test('huge attempts terminate fast with correct capped values', () => {
  const huge = Number.MAX_SAFE_INTEGER;
  const maxBudget = Number.MAX_SAFE_INTEGER;
  assert.equal(nextRetry({...base, attempt:huge}).delayMs, 100);
  assert.equal(nextRetry({...base, baseMs:0, attempt:huge}).delayMs, 0); // zero base stays zero
  assert.equal(nextRetry({...base, baseMs:1000, maxDelayMs:100, attempt:huge}).delayMs, 100); // base above cap
  assert.equal(nextRetry({...base, maxDelayMs:0, attempt:huge}).delayMs, 0);
  // boundary of the safe-integer range
  assert.equal(nextRetry({attempt:53, elapsedMs:0, baseMs:1, maxDelayMs:maxBudget, budgetMs:maxBudget, retryAfterMs:null, retryable:true}).delayMs, 2 ** 52);
  assert.equal(nextRetry({attempt:54, elapsedMs:0, baseMs:1, maxDelayMs:maxBudget, budgetMs:maxBudget, retryAfterMs:null, retryable:true}).delayMs, maxBudget);
  // huge attempts must not be slow
  const start = process.hrtime.bigint();
  for (let i = 0; i < 1000; i++) nextRetry({...base, attempt:huge});
  assert.ok(process.hrtime.bigint() - start < 1000000000n, '1000 huge-attempt calls took too long');
});

// ---------- retryAfterMs ----------

test('retryAfterMs is a minimum wait and is not capped by maxDelayMs', () => {
  assert.equal(nextRetry({...base, retryAfterMs:50}).delayMs, 50); // above exp delay
  assert.equal(nextRetry({...base, retryAfterMs:5}).delayMs, 10); // below exp delay
  assert.equal(nextRetry({...base, retryAfterMs:500}).delayMs, 500); // above maxDelayMs
  assert.equal(nextRetry({...base, retryAfterMs:0}).delayMs, 10); // zero hint
});

// ---------- budget ----------

test('budget boundary: equality is allowed, exceeding is exhausted', () => {
  const mk = overrides => nextRetry({...base, ...overrides});
  assert.deepEqual(mk({elapsedMs:990}), {retry:true, delayMs:10, reason:'scheduled'}); // exactly at boundary
  assert.deepEqual(mk({elapsedMs:991}), {retry:false, delayMs:null, reason:'budget-exhausted'}); // one ms over
  assert.deepEqual(mk({elapsedMs:1000}), {retry:false, delayMs:null, reason:'budget-exhausted'}); // elapsed == budget, positive wait
  assert.deepEqual(mk({elapsedMs:1001}), {retry:false, delayMs:null, reason:'budget-exhausted'}); // elapsed beyond budget
  assert.deepEqual(mk({elapsedMs:1001, baseMs:0}), {retry:false, delayMs:null, reason:'budget-exhausted'}); // even with zero wait
  // zero budget with zero wait is allowed (equality)
  assert.deepEqual(mk({elapsedMs:0, baseMs:0, maxDelayMs:0, budgetMs:0}), {retry:true, delayMs:0, reason:'scheduled'});
  assert.deepEqual(mk({elapsedMs:0, baseMs:1, maxDelayMs:1, budgetMs:0}), {retry:false, delayMs:null, reason:'budget-exhausted'});
  // the uncapped server hint can push the wait over the budget even when the exp delay fits
  assert.deepEqual(mk({elapsedMs:990, retryAfterMs:50}), {retry:false, delayMs:null, reason:'budget-exhausted'});
  assert.deepEqual(mk({elapsedMs:950, retryAfterMs:50}), {retry:true, delayMs:50, reason:'scheduled'});
});

// ---------- CLI ----------

function runCliWithFile(content) {
  const dir = mkdtempSync(join(tmpdir(), 'retry-budget-'));
  const file = join(dir, 'options.json');
  writeFileSync(file, content);
  try {
    return spawnSync(process.execPath, [CLI_PATH, file], {encoding:'utf8'});
  } finally {
    rmSync(dir, {recursive:true, force:true});
  }
}

test('CLI success prints exactly one JSON line, exits 0, no stderr', () => {
  const r = runCliWithFile(JSON.stringify({...base, attempt:3}));
  assert.equal(r.error, undefined);
  assert.equal(r.status, 0, r.stderr);
  assert.equal(r.stderr, '');
  assert.equal(r.stdout, `${JSON.stringify({retry:true,delayMs:40,reason:'scheduled'})}\n`);
});

test('CLI success on valid non-retry decisions (still exit 0)', () => {
  const r1 = runCliWithFile(JSON.stringify({...base, retryable:false}));
  assert.equal(r1.status, 0, r1.stderr);
  assert.equal(r1.stderr, '');
  assert.equal(r1.stdout, `${JSON.stringify({retry:false,delayMs:null,reason:'non-retryable'})}\n`);
  const r2 = runCliWithFile(JSON.stringify({...base, elapsedMs:9999}));
  assert.equal(r2.status, 0, r2.stderr);
  assert.equal(r2.stderr, '');
  assert.equal(r2.stdout, `${JSON.stringify({retry:false,delayMs:null,reason:'budget-exhausted'})}\n`);
});

test('CLI invalid JSON exits 2 with nonempty stderr and no stdout', () => {
  const r = runCliWithFile('{not json');
  assert.equal(r.status, 2);
  assert.ok(r.stderr.length > 0);
  assert.equal(r.stdout, '');
});

test('CLI with JSON values that are invalid options exits 2 with no stdout', () => {
  for (const value of ['null', '[1,2,3]', '"str"', '123', 'true', '{}', JSON.stringify({...base, attempt:'1'}), JSON.stringify({...base, retryable:0})]) {
    const r = runCliWithFile(value);
    assert.equal(r.status, 2, value);
    assert.ok(r.stderr.length > 0, value);
    assert.equal(r.stdout, '', value);
  }
});

test('CLI missing file exits 2 with nonempty stderr and no stdout', () => {
  const dir = mkdtempSync(join(tmpdir(), 'retry-budget-'));
  try {
    const r = spawnSync(process.execPath, [CLI_PATH, join(dir, 'does-not-exist.json')], {encoding:'utf8'});
    assert.equal(r.status, 2);
    assert.ok(r.stderr.length > 0);
    assert.equal(r.stdout, '');
  } finally {
    rmSync(dir, {recursive:true, force:true});
  }
});

test('CLI with zero or extra arguments exits 2 with no stdout', () => {
  for (const args of [[], ['a.json', 'b.json']]) {
    const r = spawnSync(process.execPath, [CLI_PATH, ...args], {encoding:'utf8'});
    assert.equal(r.status, 2, JSON.stringify(args));
    assert.ok(r.stderr.length > 0, JSON.stringify(args));
    assert.equal(r.stdout, '', JSON.stringify(args));
  }
});

test('importing the module does not run the CLI', () => {
  const url = new URL('../retry-budget.js', import.meta.url).href;
  const r = spawnSync(process.execPath, [
    '--input-type=module',
    '-e',
    `const m = await import(${JSON.stringify(url)}); if (typeof m.nextRetry !== 'function') process.exit(1);`,
  ], {encoding:'utf8'});
  assert.equal(r.status, 0, r.stderr);
  assert.equal(r.stdout, '');
  assert.equal(r.stderr, '');
});

