+  assert.equal(r.status, 0, r.stderr);
+  assert.equal(r.stderr, '');
+  assert.equal(r.stdout, `${JSON.stringify({retry:true,delayMs:40,reason:'scheduled'})}\n`);
+});
+
+test('CLI success on valid non-retry decisions (still exit 0)', () => {
+  const r1 = runCliWithFile(JSON.stringify({...base, retryable:false}));
+  assert.equal(r1.status, 0, r1.stderr);
+  assert.equal(r1.stderr, '');
+  assert.equal(r1.stdout, `${JSON.stringify({retry:false,delayMs:null,reason:'non-retryable'})}\n`);
+  const r2 = runCliWithFile(JSON.stringify({...base, elapsedMs:9999}));
+  assert.equal(r2.status, 0, r2.stderr);
+  assert.equal(r2.stderr, '');
+  assert.equal(r2.stdout, `${JSON.stringify({retry:false,delayMs:null,reason:'budget-exhausted'})}\n`);
+});
+
+test('CLI invalid JSON exits 2 with nonempty stderr and no stdout', () => {
+  const r = runCliWithFile('{not json');
+  assert.equal(r.status, 2);
+  assert.ok(r.stderr.length > 0);
+  assert.equal(r.stdout, '');
+});
+
+test('CLI with JSON values that are invalid options exits 2 with no stdout', () => {
+  for (const value of ['null', '[1,2,3]', '"str"', '123', 'true', '{}', JSON.stringify({...base, attempt:'1'}), JSON.stringify({...base, retryable:0})]) {
+    const r = runCliWithFile(value);
+    assert.equal(r.status, 2, value);
+    assert.ok(r.stderr.length > 0, value);
+    assert.equal(r.stdout, '', value);
+  }
+});
+
+test('CLI missing file exits 2 with nonempty stderr and no stdout', () => {
+  const dir = mkdtempSync(join(tmpdir(), 'retry-budget-'));
+  try {
+    const r = spawnSync(process.execPath, [CLI_PATH, join(dir, 'does-not-exist.json')], {encoding:'utf8'});
+    assert.equal(r.status, 2);
+    assert.ok(r.stderr.length > 0);
+    assert.equal(r.stdout, '');
+  } finally {
+    rmSync(dir, {recursive:true, force:true});
+  }
+});
+
+test('CLI with zero or extra arguments exits 2 with no stdout', () => {
+  for (const args of [[], ['a.json', 'b.json']]) {
+    const r = spawnSync(process.execPath, [CLI_PATH, ...args], {encoding:'utf8'});
+    assert.equal(r.status, 2, JSON.stringify(args));
+    assert.ok(r.stderr.length > 0, JSON.stringify(args));
+    assert.equal(r.stdout, '', JSON.stringify(args));
+  }
+});
+
+test('importing the module does not run the CLI', () => {
+  const url = new URL('../retry-budget.js', import.meta.url).href;
+  const r = spawnSync(process.execPath, [
+    '--input-type=module',
+    '-e',
+    `const m = await import(${JSON.stringify(url)}); if (typeof m.nextRetry !== 'function') process.exit(1);`,
+  ], {encoding:'utf8'});
+  assert.equal(r.status, 0, r.stderr);
+  assert.equal(r.stdout, '');
+  assert.equal(r.stderr, '');
+});

